import os
import sys

# Make the docx skill root importable without PYTHONPATH
skill_root = os.path.abspath(os.path.join(os.getcwd(), ".codex", "skills", "docx"))
if skill_root not in sys.path:
    sys.path.insert(0, skill_root)

from scripts.document import Document

doc = Document("unpacked")
editor = doc["word/document.xml"]

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"


def qn(tag):
    return "{%s}%s" % (W, tag)


def is_headline(paragraph):
    """A headline is a non-empty paragraph whose text is all uppercase."""
    texts = [
        t.firstChild.nodeValue
        for t in paragraph.getElementsByTagName("w:t")
        if t.firstChild and t.firstChild.nodeValue
    ]
    text = "".join(texts).strip()
    return bool(text) and text.isupper() and any(c.isalpha() for c in text)


headline_texts = []
for para in editor.dom.getElementsByTagName("w:p"):
    if not is_headline(para):
        continue
    texts = [
        t.firstChild.nodeValue
        for t in para.getElementsByTagName("w:t")
        if t.firstChild and t.firstChild.nodeValue
    ]
    headline_texts.append("".join(texts).strip())
    for run in para.getElementsByTagName("w:r"):
        rPr = None
        for child in run.childNodes:
            if child.nodeName == "w:rPr":
                rPr = child
                break
        if rPr is None:
            rPr = run.ownerDocument.createElement("w:rPr")
            run.insertBefore(rPr, run.firstChild)
        if not any(c.nodeName == "w:u" for c in rPr.childNodes):
            u = run.ownerDocument.createElement("w:u")
            u.setAttribute("w:val", "single")
            rPr.appendChild(u)

print("Underlined headlines:")
for h in headline_texts:
    print(" - " + h)

doc.save()
print("Saved.")

import os
import sys
from pathlib import Path

# Make the docx skill root importable without PYTHONPATH
