if skill_root not in sys.path:
    sys.path.insert(0, skill_root)

from scripts.utilities import XMLEditor

XML_PATH = "unpacked/word/document.xml"
editor = XMLEditor(XML_PATH)
dom = editor.dom

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"


def qn(tag):
    return "{%s}%s" % (W, tag)


def para_text(paragraph):
    parts = []
    for t in paragraph.getElementsByTagName("w:t"):
        if t.firstChild and t.firstChild.nodeValue:
            parts.append(t.firstChild.nodeValue)
    return "".join(parts).strip()


def is_headline(paragraph):
    text = para_text(paragraph)
    return bool(text) and text.isupper() and any(c.isalpha() for c in text)


def get_rpr(run):
    for child in run.childNodes:
        if child.nodeName == "w:rPr":
            return child
    rPr = run.ownerDocument.createElement("w:rPr")
    run.insertBefore(rPr, run.firstChild)
    return rPr


headlines = []
for para in dom.getElementsByTagName("w:p"):
    if not is_headline(para):
        continue
    headlines.append(para_text(para))
    for run in para.getElementsByTagName("w:r"):
        rPr = get_rpr(run)
        if not any(c.nodeName == "w:u" for c in rPr.childNodes):
            u = run.ownerDocument.createElement("w:u")
            u.setAttribute("w:val", "single")
            rPr.appendChild(u)

print("Underlined headlines (%d):" % len(headlines))
for h in headlines:
    print(" - " + h)

# Serialize preserving the original ascii encoding style (non-ASCII -> numeric refs)
raw = dom.toxml()
raw = raw.replace(
    '<?xml version="1.0"?>', '<?xml version="1.0" encoding="ascii"?>', 1
)
data = raw.encode("ascii", "xmlcharrefreplace")
Path(XML_PATH).write_bytes(data)
print("Saved", XML_PATH)

